import {poweredDevice,pinVoltage,logic} from './bus-electrical.js';
import {TM1637} from './tm1637.js';
const GPIO=[...Array.from({length:14},(_,i)=>'D'+i),...Array.from({length:6},(_,i)=>'A'+i)];
export function dhtFrame(type,p){const h=Math.round((p.humidity??50)*(type==='dht22'?10:1)),t=Math.round(Math.abs(p.temperature??25)*(type==='dht22'?10:1));const bytes=type==='dht22'?[h>>8,h&255,(t>>8)|((p.temperature??25)<0?128:0),t&255]:[h,0,t,0];return[...bytes,bytes.reduce((a,b)=>a+b,0)&255];}
export function hxCode(plus,minus,avdd,gain){return Math.max(-8388608,Math.min(8388607,Math.round((plus-minus)/(.5*avdd/gain)*8388608)));}
// Passive matrix closures participate in the same DC solve as GPIO pull-ups.
export function stampDigital(c,{net,branch}){
 if(c.type==='loadcell'){const r=c.params.bridgeOhms??350,delta=Math.max(-.1,Math.min(.1,(c.params.sensitivity??2)*.001*(c.params.load??500)/(c.params.capacity??1000)));for(const[id,a,b,f]of[['ap-upper','E+','A+',1-delta],['ap-lower','A+','E-',1+delta],['am-upper','E+','A-',1+delta],['am-lower','A-','E-',1-delta]])branch(c.id+':'+id,net(c,a),net(c,b),r*f);return true;}
 if(c.type==='keypad4x4'){for(let k=0;k<16;k++)if((c.params.keyMask??0)&(1<<k))branch(c.id+':key'+k,net(c,'R'+(1+(k>>2))),net(c,'C'+(1+(k&3))),.05);return true;}
 if(c.type==='tm1637'){branch(c.id+':logic-load',net(c,'VCC'),net(c,'GND'),1000);for(const pin of['CLK','DIO'])branch(c.id+':pullup:'+pin,net(c,'VCC'),net(c,pin),10000);return true;}
 if(c.type==='hx711'){branch(c.id+':excitation+',net(c,'VCC'),net(c,'E+'),.1);branch(c.id+':excitation-',net(c,'GND'),net(c,'E-'),.1);return true;}
 if(c.type==='ky040'){if(c.params.switchClosed)branch(c.id+':switch',net(c,'SW'),net(c,'GND'),.05);return true;}
 return false;
}
export function attachDigitalRuntime(runtime,engine,initial){let project=initial,devices=new Map(),disposed=false,refreshing=false,key='';
 const commit=()=>{const drivers=[];for(const d of devices.values())if(d.powered&&!d.sleep){if(d.type.startsWith('dht')&&d.sink)drivers.push({endpoint:d.id+':DATA',voltage:0,ohms:100});if(d.type==='tm1637'&&d.sink)drivers.push({endpoint:d.id+':DIO',voltage:0,ohms:100});if(d.type==='hx711')drivers.push({endpoint:d.id+':DT',voltage:d.data?d.voltage:0,ohms:50});if(d.type==='ky040')for(const[pin,bit]of[['CLK',1],['DT',2]])if(!(d.phase&bit))drivers.push({endpoint:d.id+':'+pin,voltage:0,ohms:50});}const next=JSON.stringify(drivers);if(next!==key){key=next;engine.setDrivers('digital',drivers);}};
 const later=(d,cycles,fn)=>{const epoch=d.epoch;runtime.cpu.addClockEvent(()=>{if(disposed||d.epoch!==epoch)return;fn();commit();},Math.max(1,Math.round(cycles)));};
 const refreshNow=()=>{if(!refreshing)refresh();};
 const conversion=(d,delay)=>{d.ready=false;d.data=true;const token=++d.conversion;later(d,delay,()=>{if(token!==d.conversion||!d.powered||d.sleep)return;const dc=engine.solution,a=pinVoltage(dc,d.id,d.channel+'+'),b=pinVoltage(dc,d.id,d.channel+'-'),avdd=pinVoltage(dc,d.id,'E+')-pinVoltage(dc,d.id,'E-');d.inputValid=Number.isFinite(a)&&Number.isFinite(b)&&avdd>=2.6&&a>=1.2&&b>=1.2&&a<=avdd-1.3&&b<=avdd-1.3;d.code=d.inputValid?hxCode(a,b,avdd,d.gain):0;d.word=d.code&0xffffff;d.ready=true;d.data=false;d.count=0;d.samples++;});};
 const refresh=()=>{if(disposed||refreshing)return;refreshing=true;try{const dc=engine.solution,board=project.components.find(c=>c.type==='board'),cycle=runtime.cpu.cycles;for(const d of devices.values()){const c=project.components.find(c=>c.id===d.id),power=poweredDevice(dc,d.id,{min:d.type==='dht11'?3:d.type==='dht22'||d.type==='ky040'?3.3:d.type==='hx711'?2.6:4.5}),was=d.powered;if(d.type==='ky040')power.powered=Number.isFinite(power.ground)&&Math.abs(power.ground)<.02;Object.assign(d,power);if(was&&!d.powered){d.epoch++;d.sink=false;d.controller?.reset();d.busy=false;d.active=false;d.masterLow=false;d.sleep=false;d.turning=false;d.phase=3;d.conversion++;}if(!d.powered)continue;
  if(!was){d.powerAt=cycle;d.lastRead=-Infinity;d.epoch++;if(d.type==='hx711'){d.gain=128;d.channel='A';d.sleep=false;conversion(d,(c.params.rate===80?50000:400000)*16);}}
  if(d.type.startsWith('dht')){const pin=board&&(runtime.gpioPins||GPIO).find(p=>dc.netlist.same(d.id+':DATA',board.id+':'+p));d.connected=!!pin;const s=pin&&runtime.readPin(pin),low=!!(s?.outputEnabled&&!s.high);if(low&&!d.masterLow)d.lowSince=cycle;if(!low&&d.masterLow){const width=cycle-d.lowSince,min=d.type==='dht11'?18000:1000,interval=d.type==='dht11'?1000000:2000000;if(!d.busy&&width>=min*16&&cycle-d.powerAt>=16000000&&cycle-d.lastRead>=interval*16){d.lastRead=cycle;d.frames++;d.busy=true;d.bytes=dhtFrame(d.type,c.params);let t=30*16;later(d,t,()=>d.sink=true);t+=80*16;later(d,t,()=>d.sink=false);t+=80*16;for(const byte of d.bytes)for(let b=7;b>=0;b--){later(d,t,()=>d.sink=true);t+=50*16;later(d,t,()=>d.sink=false);t+=((byte>>b)&1?70:28)*16;}later(d,t,()=>d.sink=true);later(d,t+50*16,()=>{d.sink=false;d.busy=false;});}}d.masterLow=low;d.pullup=pinVoltage(dc,d.id,'DATA')>=.7*d.voltage;
  }else if(d.type==='hx711'){const high=logic(pinVoltage(dc,d.id,'SCK'),d.voltage);if(high===true&&!d.clock){d.highSince=cycle;later(d,61*16,()=>{if(d.clock&&d.powered&&runtime.cpu.cycles-d.highSince>=60*16){d.sleep=true;d.ready=false;d.data=true;d.conversion++;}});if(d.ready){d.count++;if(d.count<=24)d.data=!!(d.word&(1<<(24-d.count)));else if(d.count<=27){const gain=d.count===25?128:d.count===26?32:64,channel=d.count===26?'B':'A',changed=d.gain!==gain||d.channel!==channel;d.gain=gain;d.channel=channel;d.data=true;conversion(d,(changed?(c.params.rate===80?50000:400000):(c.params.rate===80?12500:100000))*16);/* clock-selection tail precedes next conversion */}}else if(d.count>=25&&d.count<27){d.count++;d.gain=d.count===26?32:64;d.channel=d.count===26?'B':'A';conversion(d,(c.params.rate===80?50000:400000)*16);}}
   if(high===false&&d.clock&&d.sleep){d.sleep=false;d.gain=128;d.channel='A';d.count=0;conversion(d,(c.params.rate===80?50000:400000)*16);}d.clock=high===true;
  }else if(d.type==='tm1637'){const clk=logic(pinVoltage(dc,d.id,'CLK'),d.voltage),dio=logic(pinVoltage(dc,d.id,'DIO'),d.voltage),pin=board&&(runtime.gpioPins||GPIO).find(p=>dc.netlist.same(d.id+':DIO',board.id+':'+p)),host=pin&&runtime.readPin(pin),master=pin?(host?.outputEnabled?host.high:true):dio;d.connected=clk!==null&&dio!==null;
   if(clk&&d.prevCLK&&d.prevMaster&&!master){d.active=true;d.bits=0;d.byte=0;d.ack=0;d.sink=false;d.controller.start();}
   else if(clk&&d.prevCLK&&!d.prevMaster&&master&&!d.ack){d.active=false;d.sink=false;}
   if(d.active&&clk===true&&d.prevCLK===false){if(d.ack===1)d.ack=2;else if(!d.ack){if(d.controller.mode==='read'){/* no keyboard pins on four-terminal module: FF */}else if(dio===null){d.active=false;d.errors++;}else{d.byte|=Number(dio)<<d.bits;if(++d.bits===8){d.controller.byte(d.byte);d.ack=3;}}}}
   if(d.active&&clk===false&&d.prevCLK===true){if(d.ack===3){d.sink=true;d.ack=1;}else if(d.ack===2){d.sink=false;d.ack=0;d.bits=0;d.byte=0;}else if(d.controller.mode==='read'){d.bits=(d.bits+1)%8;d.sink=false;}}
   d.prevCLK=clk;d.prevMaster=master;
  }else if(d.type==='ky040'){const target=c.params.position??0;if(d.position!==target&&!d.turning){const direction=Math.sign(target-d.position),sequence=direction>0?[2,0,1,3]:[1,0,2,3];d.turning=true;sequence.forEach((phase,i)=>later(d,(i+1)*1000*16,()=>{d.phase=phase;if(i===3){d.position+=direction;d.turning=false;refreshNow();}}));}}
 }commit();}finally{refreshing=false;}};
 const reconcile=()=>{const ids=new Set();for(const c of project.components.filter(c=>['dht11','dht22','hx711','tm1637','ky040'].includes(c.type))){ids.add(c.id);if(!devices.has(c.id))devices.set(c.id,{id:c.id,type:c.type,epoch:0,conversion:0,powered:false,sink:false,frames:0,samples:0,count:0,phase:3,position:c.params.position??0,turning:false,errors:0,controller:c.type==='tm1637'?new TM1637():null});}for(const[id,d]of devices)if(!ids.has(id)){d.epoch++;devices.delete(id);}refresh();};reconcile();const unsubscribe=engine.subscribe(refresh);
 return{updateProject(next){project=next;reconcile();},snapshot(){refresh();return{modules:Object.fromEntries([...devices].map(([id,d])=>[id,{type:d.type,powered:d.powered,connected:d.connected??true,voltage:d.voltage,frames:d.frames,busy:d.busy,bytes:d.bytes,pullup:d.pullup,code:d.code,inputValid:d.inputValid,gain:d.gain,channel:d.channel,ready:d.ready,sleep:d.sleep,samples:d.samples,position:d.position,phase:d.phase,errors:d.errors,...d.controller?.state()}]))};},dispose(){disposed=true;for(const d of devices.values())d.epoch++;unsubscribe();engine.setDrivers('digital',[]);}};
}
